window.renderAnnualPlayerRanking=block=>`<div class="annual-poster"><div class="annual-poster-heading"><span>${escapeHtml(block.organizer||({2017:"TSL",2018:"TSL",2019:"GSE",2020:"GSE",2021:"GSE / SUVOH",2023:"RANK S",2024:"RANK S",2025:"BCN"}[block.year])||"RANKING MUNDIAL")} · BLOCK STRIKE</span><strong>TOP 20 <b>${block.year}</b></strong><small>Os jogadores que marcaram a temporada</small></div><ol class="annual-poster-grid" aria-label="Top 20 jogadores de ${block.year}">${[...block.entries].sort((a,b)=>a.rank-b.rank).map(entry=>{const H=window.HBSTV,name=H?.name(entry.name)||entry.name,country=entry.country||"BR",countryName=({BR:"Brasil",AR:"Argentina",DE:"Alemanha",LT:"Lituânia",RU:"Rússia",UA:"Ucrânia",FR:"França"}[country])||country,flag=/^[A-Z]{2}$/.test(country)?String.fromCodePoint(...[...country].map(c=>127397+c.charCodeAt(0))):country;return `<li class="annual-poster-card annual-place-${entry.rank}"><a href="${H?.playerHref(entry.name)||'#jogadores-todos'}" aria-label="${escapeHtml(name)}, posição ${entry.rank} em ${block.year}, ${escapeHtml(countryName)}${entry.team?", equipe "+escapeHtml(entry.team):""}"><span class="annual-poster-rank">${entry.rank}</span><img src="assets/player-silhouette.svg" alt="" loading="lazy"><span class="annual-poster-player"><strong>${escapeHtml(name)}</strong><small><span aria-label="${escapeHtml(countryName)}">${flag}</span> ${escapeHtml(entry.team||country)}</small></span></a></li>`}).join('')}</ol></div><p class="source-note">${escapeHtml(block.year===2017?"Ranking de 2017 realizado pela TSL. Dados fornecidos pelo responsável pelo site.":block.source)}</p>`;

window.annualPosterYearByImage={"6652defb394ed8db2450.jpg":2018,"d806b306a3bef83a8d2e.jpg":2019,"f6897efedb69b3129634.jpg":2020,"4f2241c33edc8dcdd40b.jpg":2021,"ae98814e259a1bf1ab04.jpeg":2023,"2fb391fe6e52c0fd23ce.jpg":2024,"4898e009960bf1d06e47.jpeg":2025};
